namespace MailKitCache
{
	public class CachedImapClient : ImapClient
	{
		public CachedImapClient (string cacheDir, IProtocolLogger protocolLogger) : base (protocolLogger)
		{
			CacheDir = cacheDir;
		}

		public CachedImapClient (string cacheDir) : base ()
		{
			CacheDir = cacheDir;
		}

